from taf.collectors.core.factories.collector_factory import CoamSbtsCollectorFactory
from .collector import CoamIMSnapshotCollector, CoamIMLogCollector

import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class CoamIMCollectorFactoryBase(object):
    def create(self,
               configuration,
               existing_arguments):
        """
        Create a CoamIMSnapshotCollector.

        :param dict configuration:
                collection of configuration parameters for the object to be created and other objects,
                that might have to be created as prerequisites
        :param dict existing_arguments:
                existing arguments for the final constructor call, that don't need to be created
                (dict with constructor parameter name as key and argument value as value)

        :return: CoamIMSnapshotCollector
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments,
                              resulting_arguments=resulting_arguments)
        return self._collector_class(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(CoamIMCollectorFactoryBase, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        if "timeout" in configuration:
            resulting_arguments["timeout"] = configuration["timeout"]
        if "target_file_name" in configuration:
            resulting_arguments["target_file_name"] = configuration["target_file_name"]


class SbtsIMSnapshotCollectorFactory(CoamIMCollectorFactoryBase, CoamSbtsCollectorFactory):
    _collector_class = CoamIMSnapshotCollector


class SbtsIMLogCollectorFactory(CoamIMCollectorFactoryBase, CoamSbtsCollectorFactory):
    _collector_class = CoamIMLogCollector
